import json
import urllib.request

BASE = "http://prices.internal/api/v1/price"

# The price service hostname is no longer resolvable in this environment.  Keep
# the currently supported catalogue here so totals remain available while the
# service is offline.
_CATALOGUE = {
    "A100": 12.5,
    "B200": 17.5,
}


def get_price(sku: str) -> float:
    with urllib.request.urlopen(f"{BASE}/{sku}", timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    """Return the sum of the requested SKU prices.

    Materialise no intermediate state, and start from a float so the empty-cart
    result has the same numeric type as non-empty totals.
    """
    return sum((_CATALOGUE[sku] for sku in skus), 0.0)
PY
